import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.channels.OverlappingFileLockException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path p = Path.of("lock.dat");
        Files.write(p, "0123456789".getBytes(StandardCharsets.US_ASCII));

        try (FileChannel ch = FileChannel.open(p, StandardOpenOption.READ, StandardOpenOption.WRITE);
             FileLock lock = ch.lock()) {
            System.out.println("exclusive lock acquired    : " + lock.isValid());
            System.out.println("lock range [pos,end)      : [" + lock.position() + ", "
                    + (lock.position() + lock.size()) + ")");
            System.out.println("  (whole-file lock reports size()=Long.MAX_VALUE, "
                    + "not the file length " + Files.size(p) + ")");

            // a second channel in the SAME JVM must fail with OverlappingFileLockException
            boolean overlapping = false;
            try (FileChannel ch2 = FileChannel.open(p, StandardOpenOption.READ, StandardOpenOption.WRITE)) {
                ch2.tryLock();
            } catch (OverlappingFileLockException e) {
                overlapping = true;
            }
            System.out.println("2nd lock in SAME JVM -> exception : " + overlapping);
            System.out.println("  (same JVM overlap throws OverlappingFileLockException, "
                    + "while another PROCESS would make tryLock() return null)");

            ByteBuffer buf = ByteBuffer.wrap("XY".getBytes(StandardCharsets.US_ASCII));
            ch.write(buf, 0);
        }
        System.out.println("after release, content      : "
                + Files.readString(p, StandardCharsets.US_ASCII));

        // atomic replace inside the same filesystem
        Path tmp = Path.of("lock.dat.tmp");
        Files.writeString(tmp, "REPLACED");
        Files.move(tmp, p, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        System.out.println("atomic move succeeded      : " + !Files.exists(tmp));
        System.out.println("final content              : " + Files.readString(p, StandardCharsets.US_ASCII));
        System.out.println("ATOMIC_MOVE is only guaranteed within one filesystem");
    }
}
